import json
from pathlib import Path

home = Path.home()
runtime_root = home / ".do_again/projects/41857a676462/runtime"
daemon = runtime_root / "do_again/service/daemon.py"
browser = runtime_root / "do_again/browser/runtime.py"

def info(path):
    if not path.exists():
        return {"exists": False}
    text = path.read_text()
    return {
        "exists": True,
        "path": str(path),
        "has_notify_receipts": "notify_receipts" in text,
        "has_batch_limit_20": "paths[:20]" in text,
        "has_wait_for_response_false": "wait_for_response=False" in text,
    }

print(json.dumps({
    "runtime_root": str(runtime_root),
    "daemon": info(daemon),
    "browser": info(browser),
}, indent=2))
